            sub_s = s[i:j]
            for k in range(m):
                for l in range(k + 1, m + 1):
                    sub_t = t[k:l]
                    combined = sub_s + sub_t
                    if is_palindrome(combined):
                        max_len = max(max_len, len(combined))

    # 別忘了子字串可以是空的
    # 如果 s 選空，則就是 t 的最大回文；如果 t 選空，則是 s 的最大回文。
    # 以上迴圈已包含這些情況（當 i=j 或 k=l 時）。

    # 考慮到題目 "selecting a substring"，若沒選到任何字串長度為 0，但有字元時至少是 1
    if max_len == 0 and (n > 0 or m > 0):
        return 1

    return max_len

# 因為題目限制很小 (30)，上面的 O(N^2 * M^2) 是可行的。
# 但為了更精確符合 "concatenating them in order"，通常是指 s 的子字串接在 t 的子字串前面。
# 重新整理後的簡潔邏輯：
def longestPalindrome(s: str, t: str) -> int:
    res = 0
    # 預先找出所有可能的子字串組合
    # 因為 N, M <= 30，直接暴力檢查所有 sub_s + sub_t
    for i in range(len(s) + 1):
        for j in range(i, len(s) + 1):
            sub_s = s[i:j]
            for k in range(len(t) + 1):
                for l in range(k, len(t) + 1):
                    sub_t = t[k:l]
                    combined = sub_s + sub_t
                    if combined == combined[::-1]:
                        res = max(res, len(combined))
    return res
