from typing import List
import sys

def findMaximumScore(nums: List[int]) -> int:
    sys.setrecursionlimit(200000)
    n = len(nums)
    if n <= 1:
        return 0

    # dp[j] = max_{i < j} (dp[i] + (j - i) * nums[i])
    # dp[j] = max_{i < j} (nums[i] * j + (dp[i] - i * nums[i]))
    # Line: y = m*x + c where x is index j, m = nums[i], c = dp[i] - i * nums[i]

    tree_size = 1 << (n).bit_length()
    tree = [None] * (4 * tree_size)

    def update(v, tl, tr, m, c):
        mid = (tl + tr) // 2
        if tree[v] is None:
            tree[v] = (m, c)
            return

        m_old, c_old = tree[v]
        f_new_mid = m * mid + c
        f_old_mid = m_old * mid + c_old

        if f_new_mid > f_old_mid:
            tree[v] = (m, c)
            # The old line becomes the "loser" to be pushed down
            m, c = m_old, c_old 

        if tl == tr:
            return

        f_new_l = m * tl + c
        f_old_l = m_old * tl + c_old # Note: m_old is the winner at mid
        # If f_new wins on the left, push to left child.
        if f_new_l > f_old_l:
            update(2*v, tl, mid, m, c)
        else:
            update(2*v+1, mid+1, tr, m, c)

    def query(v, tl, tr, x):
        if tree[v] is None:
            return -float('inf')
        m, c = tree[v]
        res = m * x + c
        if tl == tr:
            return res
        mid = (tl + tr) // 2
        if x <= mid:
            return max(res, query(2*v, tl, mid, x))
        else:
            return max(res, query(2*v+1, mid+1, tr, x))

    # Initial state at index 0
    update(1, 0, tree_size - 1, nums[0], 0)

    dp = [0] * n
    for j in range(1, n):
        res = query(1, 0, tree_size - 1, j)
        # If the result is still -inf (shouldn't happen for valid indices), use 0
        dp[j] = res if res != -float('inf') else 0
        update(1, 0, tree_size - 1, nums[j], dp[j] - j * nums[j])

    return int(dp[n-1])
